import path from "node:path";
import process from "node:process";

/**
 * Every project path the build tooling touches, relative to the project root
 * (posix separators). Nothing else in build/ hardcodes one: when a file moves,
 * this is the only place to edit.
 */
export const PATHS = {
  /** The report itself (parsed by the shiki plugin). */
  report: "src/report.mdx",
  /** Hand-written theme baseline (design tokens). */
  baselineCss: "src/styles/tokens.css",
  /** Overrides generated by the ThemePanel. */
  themeOverrides: "src/custom/variables/vars.css",
  /** Report media, listed by the export panel. */
  assets: "src/assets",
  /** Asset exclusion rules for the hybrid build. */
  assetsConfig: "report.assets.config.json",
  /** Pre-rendered mermaid SVGs: inputs of the production build, keep them committed. */
  mermaidSvgs: "src/generated/mermaid",
  /** Entry of `npm run build:*`, also spawned by the export panel. */
  buildScript: "build/build-report.mjs",
} as const;

export type PathKey = keyof typeof PATHS;

export function resolvePath(key: PathKey, root: string = process.cwd()): string {
  return path.resolve(root, PATHS[key]);
}
